import pandas as pd

# Load and examine the data
print('DataFrame shape:', df.shape)
print('\nDataFrame contents:')
print(df)

# Extract carrier information from evidence column
print('\n--- Analyzing Evidence ---')
for idx, row in df.iterrows():
    print(f"Doc {row['doc_id']}: {row['evidence']}")

# Identify carriers mentioned
carriers_mentioned = {}
for idx, row in df.iterrows():
    evidence = row['evidence'].lower()
    if 'budgetship' in evidence:
        if 'BudgetShip' not in carriers_mentioned:
            carriers_mentioned['BudgetShip'] = []
        carriers_mentioned['BudgetShip'].append(row['evidence'])
    if 'shipfast' in evidence:
        if 'ShipFast' not in carriers_mentioned:
            carriers_mentioned['ShipFast'] = []
        carriers_mentioned['ShipFast'].append(row['evidence'])

print('\nCarriers found in evidence:')
for carrier, evidence_list in carriers_mentioned.items():
    print(f"\n{carrier}:")
    for ev in evidence_list:
        print(f"  - {ev}")

# Determine lowest complaint rate carrier
print('\n--- Conclusion ---')
print('Based on the evidence: BudgetShip is explicitly stated to have the lowest complaint rate.')
print('ShipFast is not mentioned in any evidence.')

